import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'طلب فتح المتجر',rank:5};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};export default function P(){const[f,setF]=useState<any>({owner_name:'',store_name:'',email:'',phone:'',city:'',address:'',governorate:'',logo_url:'',latitude:'',longitude:'',google_maps_url:'',application_status:'pending',rejection_reason:''}),[m,setM]=useState('');useEffect(()=>{api('/vendor/spike/store-profile').then(d=>setF((x:any)=>({...x,...(d.profile||{}),store_name:d.profile?.store_name||d.seller?.name||'',email:d.profile?.email||d.seller?.email||''}))).catch(e=>setM(e.message))},[]);const save=async()=>{try{const d=await api('/vendor/spike/store-profile',{method:'POST',body:JSON.stringify(f)});setF((x:any)=>({...x,...d.profile}));setM('تم إرسال طلب فتح المتجر للإدارة للمراجعة')}catch(e:any){setM(e.message)}};const status=f.application_status==='approved'?'تمت الموافقة على المتجر':f.application_status==='rejected'?'تم رفض الطلب':'قيد المراجعة';return <div dir="rtl" style={{padding:24,maxWidth:850}}><h1>طلب فتح المتجر</h1><p>أكمل جميع البيانات التالية. لن يصبح المتجر فعالاً حتى توافق الإدارة.</p><p><b>الحالة:</b> {status}</p>{f.rejection_reason&&<p style={{color:'#a40000'}}><b>سبب الرفض:</b> {f.rejection_reason}</p>}{m&&<p>{m}</p>}<div style={{display:'grid',gridTemplateColumns:'repeat(2,minmax(0,1fr))',gap:10}}><input placeholder="اسم صاحب المتجر" value={f.owner_name} onChange={e=>setF({...f,owner_name:e.target.value})}/><input placeholder="اسم المتجر" value={f.store_name} onChange={e=>setF({...f,store_name:e.target.value})}/><input type="email" placeholder="البريد الإلكتروني" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/><input placeholder="رقم الهاتف" value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/><input placeholder="المدينة" value={f.city} onChange={e=>setF({...f,city:e.target.value})}/><input placeholder="العنوان" value={f.address} onChange={e=>setF({...f,address:e.target.value})}/><input placeholder="المحافظة" value={f.governorate} onChange={e=>setF({...f,governorate:e.target.value})}/><input placeholder="رابط شعار المتجر" value={f.logo_url} onChange={e=>setF({...f,logo_url:e.target.value})}/><input placeholder="رابط Google Maps" value={f.google_maps_url} onChange={e=>setF({...f,google_maps_url:e.target.value})}/><span></span><input type="number" step="any" placeholder="Latitude اختياري" value={f.latitude??''} onChange={e=>setF({...f,latitude:e.target.value})}/><input type="number" step="any" placeholder="Longitude اختياري" value={f.longitude??''} onChange={e=>setF({...f,longitude:e.target.value})}/></div><button style={{marginTop:16}} onClick={save}>إرسال / تحديث الطلب</button></div>}
